=== FILE: rtl/axil_timer.v ===
`timescale 1ns/1ps
`default_nettype none

// axil_timer: 32-bit down-counting timer, one-shot and periodic modes, level
// interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md per microarchitecture.md.
//
// Register map (byte offsets):
//   0x0 CTRL   rw   bit0 EN, bit1 IE, bit2 MODE (0 one-shot, 1 periodic)
//   0x4 LOAD   rw   count length in cycles (0 counts as 1)
//   0x8 COUNT  ro   cycles left; writes get SLVERR
//   0xC STATUS w1c  bit0 EXPIRED
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,

    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,

    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,

    output reg  [1:0]            s_axil_bresp,
    output reg                   s_axil_bvalid,
    input  wire                  s_axil_bready,

    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,

    output reg  [31:0]           s_axil_rdata,
    output reg  [1:0]            s_axil_rresp,
    output reg                   s_axil_rvalid,
    input  wire                  s_axil_rready,

    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] IDX_CTRL   = 2'd0;
    localparam [1:0] IDX_LOAD   = 2'd1;
    localparam [1:0] IDX_COUNT  = 2'd2;
    localparam [1:0] IDX_STATUS = 2'd3;

    // ------------------------------------------------------------------
    // Write channel holding state (microarchitecture section 1)
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg                  w_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;

    // ------------------------------------------------------------------
    // Timer state (microarchitecture section 2)
    // ------------------------------------------------------------------
    reg        en;
    reg        ie;
    reg        mode;
    reg        expired;
    reg [31:0] load;
    reg [31:0] count;

    assign s_axil_awready = !aw_held && !s_axil_bvalid;
    assign s_axil_wready  = !w_held  && !s_axil_bvalid;
    assign s_axil_arready = !s_axil_rvalid;

    wire aw_hs = s_axil_awvalid && s_axil_awready;
    wire w_hs  = s_axil_wvalid  && s_axil_wready;

    // Both halves present (held or arriving): the write takes effect now.
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    // Address decode (microarchitecture section 3): word aligned and below 0x10.
    wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                           ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] wr_idx    = wr_addr[3:2];

    wire wr_okay  = wr_mapped && (wr_idx != IDX_COUNT);
    wire wr_ctrl  = do_write && wr_mapped && (wr_idx == IDX_CTRL) && wr_strb[0];
    wire wr_load  = do_write && wr_mapped && (wr_idx == IDX_LOAD);
    wire wr_clear = do_write && wr_mapped && (wr_idx == IDX_STATUS) &&
                    wr_strb[0] && wr_data[0];

    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                           ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] rd_idx    = s_axil_araddr[3:2];

    reg [31:0] rd_value;
    always @(*) begin
        case (rd_idx)
            IDX_CTRL:  rd_value = {29'd0, mode, ie, en};
            IDX_LOAD:  rd_value = load;
            IDX_COUNT: rd_value = count;
            default:   rd_value = {31'd0, expired};
        endcase
    end

    // ------------------------------------------------------------------
    // AXI4-Lite channels
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held       <= 1'b0;
            w_held        <= 1'b0;
            s_axil_bvalid <= 1'b0;
            s_axil_bresp  <= RESP_OKAY;
            s_axil_rvalid <= 1'b0;
            s_axil_rdata  <= 32'd0;
            s_axil_rresp  <= RESP_OKAY;
        end else begin
            if (do_write) begin
                aw_held       <= 1'b0;
                w_held        <= 1'b0;
                s_axil_bvalid <= 1'b1;
                s_axil_bresp  <= wr_okay ? RESP_OKAY : RESP_SLVERR;
            end else begin
                if (aw_hs) begin
                    aw_held <= 1'b1;
                end
                if (w_hs) begin
                    w_held <= 1'b1;
                end
                if (s_axil_bvalid && s_axil_bready) begin
                    s_axil_bvalid <= 1'b0;
                end
            end

            if (s_axil_arvalid && s_axil_arready) begin
                s_axil_rvalid <= 1'b1;
                s_axil_rdata  <= rd_mapped ? rd_value : 32'd0;
                s_axil_rresp  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
            end else if (s_axil_rvalid && s_axil_rready) begin
                s_axil_rvalid <= 1'b0;
            end
        end
    end

    // Held address and data: read only while a holding flag is set, so they
    // need no reset (microarchitecture section 4).
    always @(posedge aclk) begin
        if (aw_hs) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Timer. The statement order gives the specification's priorities by
    // last-assignment-wins:
    //   1. count step  2. expired clear, then set  3. CTRL write  4. LOAD write
    // ------------------------------------------------------------------
    wire count_end = en && (count <= 32'd1);

    always @(posedge aclk) begin
        if (!aresetn) begin
            en      <= 1'b0;
            ie      <= 1'b0;
            mode    <= 1'b0;
            expired <= 1'b0;
            load    <= 32'd0;
            count   <= 32'd0;
        end else begin
            // 1. Count step
            if (en) begin
                if (count_end) begin
                    if (mode) begin
                        count <= load;
                    end else begin
                        count <= 32'd0;
                        en    <= 1'b0;
                    end
                end else begin
                    count <= count - 32'd1;
                end
            end

            // 2. Expiry: a count end beats a clear
            if (wr_clear) begin
                expired <= 1'b0;
            end
            if (count_end) begin
                expired <= 1'b1;
            end

            // 3. CTRL write (only with wstrb[0]); wins for en and count
            if (wr_ctrl) begin
                ie   <= wr_data[1];
                mode <= wr_data[2];
                if (wr_data[0]) begin
                    en    <= 1'b1;
                    count <= load;
                end else begin
                    en <= 1'b0;
                end
            end

            // 4. LOAD write, byte by byte
            if (wr_load) begin
                if (wr_strb[0]) load[7:0]   <= wr_data[7:0];
                if (wr_strb[1]) load[15:8]  <= wr_data[15:8];
                if (wr_strb[2]) load[23:16] <= wr_data[23:16];
                if (wr_strb[3]) load[31:24] <= wr_data[31:24];
            end
        end
    end

    assign irq = expired && ie;

`ifdef FORMAL
    // Design-intent assertions (unproven; no formal job accompanies this file).
    reg f_past_valid = 1'b0;
    reg f_rst_seen   = 1'b0;
    always @(posedge aclk) begin
        f_past_valid <= 1'b1;
        if (!aresetn) begin
            f_rst_seen <= 1'b1;
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && f_rst_seen && $past(aresetn)) begin
            if ($past(s_axil_bvalid && !s_axil_bready))
                assert (s_axil_bvalid && (s_axil_bresp == $past(s_axil_bresp)));
            if ($past(s_axil_rvalid && !s_axil_rready))
                assert (s_axil_rvalid && (s_axil_rdata == $past(s_axil_rdata)) &&
                        (s_axil_rresp == $past(s_axil_rresp)));
            if ($past(count_end))
                assert (expired);
            if ($past(count_end && !mode && !wr_ctrl))
                assert (!en && (count == 32'd0));
            if ($past(en && !count_end && !wr_ctrl))
                assert (count == $past(count) - 32'd1);
            if ($past(!en && !wr_ctrl))
                assert (count == $past(count));
            assert (!(s_axil_bvalid && (aw_held || w_held)));
            assert (irq == (expired && ie));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: tb/axil_timer_tb.v ===
`timescale 1ns/1ps
`default_nettype none

// Self-checking testbench for axil_timer.
// One stimulus drives two lanes in lockstep: dut4 (ADDR_WIDTH 4) and
// dut8 (ADDR_WIDTH 8). Offsets from 0x10 up are sent to dut8 only
// (lane4_en low). A posedge monitor checks the channel rules on dut8 and
// that dut4 agrees with dut8 cycle by cycle.
// Stimulus is driven on the falling edge; cyc counts rising edges, so at a
// falling edge cyc is the number of the rising edge just passed.
module axil_timer_tb;

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg clk = 1'b0;
    always #5 clk = ~clk;
    reg aresetn = 1'b0;

    reg [7:0]  awaddr   = 8'h00;
    reg        awvalid  = 1'b0;
    reg [31:0] wdata    = 32'h0;
    reg [3:0]  wstrb    = 4'h0;
    reg        wvalid   = 1'b0;
    reg        bready   = 1'b0;
    reg [7:0]  araddr   = 8'h00;
    reg        arvalid  = 1'b0;
    reg        rready   = 1'b0;
    reg        lane4_en = 1'b1;

    wire awvalid4 = awvalid & lane4_en;
    wire wvalid4  = wvalid  & lane4_en;
    wire bready4  = bready  & lane4_en;
    wire arvalid4 = arvalid & lane4_en;
    wire rready4  = rready  & lane4_en;

    wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
    wire [1:0]  bresp4, rresp4;
    wire [31:0] rdata4;
    wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
    wire [1:0]  bresp8, rresp8;
    wire [31:0] rdata8;

    axil_timer #(.ADDR_WIDTH(4)) dut4 (
        .aclk(clk), .aresetn(aresetn),
        .s_axil_awaddr(awaddr[3:0]), .s_axil_awvalid(awvalid4), .s_axil_awready(awready4),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid4), .s_axil_wready(wready4),
        .s_axil_bresp(bresp4), .s_axil_bvalid(bvalid4), .s_axil_bready(bready4),
        .s_axil_araddr(araddr[3:0]), .s_axil_arvalid(arvalid4), .s_axil_arready(arready4),
        .s_axil_rdata(rdata4), .s_axil_rresp(rresp4), .s_axil_rvalid(rvalid4), .s_axil_rready(rready4),
        .irq(irq4)
    );

    axil_timer #(.ADDR_WIDTH(8)) dut8 (
        .aclk(clk), .aresetn(aresetn),
        .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready8),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready8),
        .s_axil_bresp(bresp8), .s_axil_bvalid(bvalid8), .s_axil_bready(bready),
        .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready8),
        .s_axil_rdata(rdata8), .s_axil_rresp(rresp8), .s_axil_rvalid(rvalid8), .s_axil_rready(rready),
        .irq(irq8)
    );

    integer passed        = 0;
    integer failed        = 0;
    integer nchk          = 0;
    integer phase         = 0;
    integer cyc           = 0;
    integer mon_fail      = 0;
    integer last_irq_rise = -1;
    integer irq_rises     = 0;
    integer last_wr_edge  = 0;
    integer last_rd_edge  = 0;
    integer rc            = 0;
    reg [8*64-1:0] nonce  = 512'd0;

    // ------------------------------------------------------------------
    // Monitor: samples pre-edge values at every rising edge.
    // ------------------------------------------------------------------
    reg        p_rst    = 1'b0;
    reg        p_bvalid = 1'b0;
    reg        p_bready = 1'b0;
    reg [1:0]  p_bresp  = 2'b00;
    reg        p_rvalid = 1'b0;
    reg        p_rready = 1'b0;
    reg [1:0]  p_rresp  = 2'b00;
    reg [31:0] p_rdata  = 32'd0;
    reg        p_irq    = 1'b0;

    always @(posedge clk) begin
        cyc <= cyc + 1;
        if (p_rst) begin
            if (p_bvalid && !p_bready && (!bvalid8 || (bresp8 != p_bresp))) begin
                mon_fail = mon_fail + 1;
                $error("monitor: B channel changed before BREADY (after edge %0d)", cyc);
            end
            if (p_rvalid && !p_rready &&
                (!rvalid8 || (rdata8 != p_rdata) || (rresp8 != p_rresp))) begin
                mon_fail = mon_fail + 1;
                $error("monitor: R channel changed before RREADY (after edge %0d)", cyc);
            end
        end
        if (bvalid8 && (awready8 || wready8)) begin
            mon_fail = mon_fail + 1;
            $error("monitor: AWREADY/WREADY high while BVALID (after edge %0d)", cyc);
        end
        if (rvalid8 && arready8) begin
            mon_fail = mon_fail + 1;
            $error("monitor: ARREADY high while RVALID (after edge %0d)", cyc);
        end
        if (irq4 != irq8) begin
            mon_fail = mon_fail + 1;
            $error("monitor: irq differs between lanes (after edge %0d)", cyc);
        end
        if (lane4_en) begin
            if ((awready4 != awready8) || (wready4 != wready8) || (arready4 != arready8) ||
                (bvalid4 != bvalid8) || (rvalid4 != rvalid8)) begin
                mon_fail = mon_fail + 1;
                $error("monitor: channel handshake differs between lanes (after edge %0d)", cyc);
            end
            if (bvalid8 && (bresp4 != bresp8)) begin
                mon_fail = mon_fail + 1;
                $error("monitor: BRESP differs between lanes (after edge %0d)", cyc);
            end
            if (rvalid8 && ((rdata4 != rdata8) || (rresp4 != rresp8))) begin
                mon_fail = mon_fail + 1;
                $error("monitor: read data differs between lanes (after edge %0d)", cyc);
            end
        end
        if (irq8 && !p_irq) begin
            last_irq_rise = cyc;
            irq_rises     = irq_rises + 1;
        end
        p_rst    = aresetn;
        p_bvalid = bvalid8;
        p_bready = bready;
        p_bresp  = bresp8;
        p_rvalid = rvalid8;
        p_rready = rready;
        p_rresp  = rresp8;
        p_rdata  = rdata8;
        p_irq    = irq8;
    end

    // ------------------------------------------------------------------
    // Check helpers
    // ------------------------------------------------------------------
    task chk(input ok);
        begin
            nchk = nchk + 1;
            if (ok) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check #%0d failed (phase %0d, edge %0d)", nchk, phase, cyc);
            end
        end
    endtask

    task chk32(input [31:0] got, input [31:0] want);
        begin
            nchk = nchk + 1;
            if (got === want) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check #%0d failed (phase %0d, edge %0d): got 0x%08h, expected 0x%08h",
                       nchk, phase, cyc, got, want);
            end
        end
    endtask

    task chk_resp(input [1:0] got, input [1:0] want);
        begin
            chk32({30'd0, got}, {30'd0, want});
        end
    endtask

    task tb_fail(input integer code);
        begin
            failed = failed + 1;
            $error("transfer failure %0d (phase %0d, edge %0d)", code, phase, cyc);
        end
    endtask

    task idle(input integer n);
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) @(negedge clk);
        end
    endtask

    // Return at the falling edge after rising edge e.
    task wait_edge(input integer e);
        begin
            while (cyc < e) @(negedge clk);
        end
    endtask

    // Wait for irq, then one more cycle so the monitor records the rise.
    task wait_irq(input integer limit);
        integer g;
        begin
            g = 0;
            while (!irq8 && (g < limit)) begin
                @(negedge clk);
                g = g + 1;
            end
            chk(irq8 == 1'b1);
            @(negedge clk);
        end
    endtask

    // ------------------------------------------------------------------
    // AXI4-Lite manager tasks (called at a falling edge, return at one)
    // ------------------------------------------------------------------
    task axi_write(input [7:0] addr, input [31:0] data, input [3:0] strb,
                   input integer aw_dly, input integer w_dly, input integer b_dly,
                   output [1:0] resp);
        integer k;
        integer guard;
        reg aw_pend, w_pend, hs_aw, hs_w;
        begin
            awaddr  = addr;
            wdata   = data;
            wstrb   = strb;
            aw_pend = 1'b1;
            w_pend  = 1'b1;
            k       = 0;
            guard   = 0;
            while ((aw_pend || w_pend) && (guard < 200)) begin
                awvalid = aw_pend && (k >= aw_dly);
                wvalid  = w_pend  && (k >= w_dly);
                hs_aw   = awvalid && awready8;
                hs_w    = wvalid  && wready8;
                if (bvalid8) tb_fail(1);
                @(negedge clk);
                if (hs_aw) aw_pend = 1'b0;
                if (hs_w)  w_pend  = 1'b0;
                k     = k + 1;
                guard = guard + 1;
            end
            awvalid      = 1'b0;
            wvalid       = 1'b0;
            last_wr_edge = cyc;
            if (guard >= 200) tb_fail(2);
            if (!bvalid8) tb_fail(3);
            k = 0;
            while (k < b_dly) begin
                if (!bvalid8) tb_fail(4);
                @(negedge clk);
                k = k + 1;
            end
            bready = 1'b1;
            if (!bvalid8) tb_fail(5);
            resp = bresp8;
            @(negedge clk);
            bready = 1'b0;
            if (bvalid8) tb_fail(6);
        end
    endtask

    task axi_read(input [7:0] addr, input integer r_dly,
                  output [31:0] data, output [1:0] resp);
        integer k;
        integer guard;
        reg hs;
        begin
            araddr  = addr;
            arvalid = 1'b1;
            hs      = 1'b0;
            guard   = 0;
            while (!hs && (guard < 200)) begin
                hs = arready8;
                if (rvalid8) tb_fail(11);
                @(negedge clk);
                guard = guard + 1;
            end
            arvalid      = 1'b0;
            last_rd_edge = cyc;
            if (!hs) tb_fail(12);
            k = 0;
            while (k < r_dly) begin
                if (!rvalid8) tb_fail(13);
                @(negedge clk);
                k = k + 1;
            end
            rready = 1'b1;
            if (!rvalid8) tb_fail(14);
            data = rdata8;
            resp = rresp8;
            @(negedge clk);
            rready = 1'b0;
            if (rvalid8) tb_fail(15);
        end
    endtask

    task wr(input [7:0] addr, input [31:0] data, input [3:0] strb, input [1:0] want_resp);
        reg [1:0] wresp;
        begin
            axi_write(addr, data, strb, 0, 0, 0, wresp);
            chk_resp(wresp, want_resp);
        end
    endtask

    task rd_chk(input [7:0] addr, input [31:0] want, input [1:0] want_resp);
        reg [31:0] rdat;
        reg [1:0]  rrsp;
        begin
            axi_read(addr, 0, rdat, rrsp);
            chk32(rdat, want);
            chk_resp(rrsp, want_resp);
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    integer    E;
    integer    E2;
    integer    S;
    integer    W;
    integer    rises0;
    integer    expv;
    reg [31:0] d;
    reg [1:0]  r;

    initial begin
        rc = $value$plusargs("nirmaan_nonce=%s", nonce);

        aresetn = 1'b0;
        idle(4);
        aresetn = 1'b1;

        // 1. Reset values
        phase = 1;
        chk(awready8 && wready8 && arready8 && !bvalid8 && !rvalid8 && !irq8);
        chk(awready4 && wready4 && arready4 && !bvalid4 && !rvalid4 && !irq4);
        rd_chk(8'h00, 32'h0, OKAY);
        rd_chk(8'h04, 32'h0, OKAY);
        rd_chk(8'h08, 32'h0, OKAY);
        rd_chk(8'h0C, 32'h0, OKAY);

        // 2. LOAD with partial strobes
        phase = 2;
        wr(8'h04, 32'h11223344, 4'hF, OKAY);
        rd_chk(8'h04, 32'h11223344, OKAY);
        wr(8'h04, 32'hAABBCCDD, 4'b0101, OKAY);
        rd_chk(8'h04, 32'h11BB33DD, OKAY);
        wr(8'h04, 32'h55667788, 4'b1010, OKAY);
        rd_chk(8'h04, 32'h55BB77DD, OKAY);
        wr(8'h04, 32'h00000000, 4'b0000, OKAY);
        rd_chk(8'h04, 32'h55BB77DD, OKAY);

        // 3. Channel orders and backpressure
        phase = 3;
        axi_write(8'h04, 32'h01020304, 4'hF, 0, 3, 0, r);   // address first
        chk_resp(r, OKAY);
        rd_chk(8'h04, 32'h01020304, OKAY);
        axi_write(8'h04, 32'h0A0B0C0D, 4'hF, 3, 0, 2, r);   // data first
        chk_resp(r, OKAY);
        rd_chk(8'h04, 32'h0A0B0C0D, OKAY);
        axi_write(8'h04, 32'hCAFEF00D, 4'hF, 2, 2, 5, r);   // together, late
        chk_resp(r, OKAY);
        axi_read(8'h04, 4, d, r);                            // read backpressure
        chk32(d, 32'hCAFEF00D);
        chk_resp(r, OKAY);

        // 4. COUNT read only and the SLVERR policy
        phase = 4;
        rd_chk(8'h08, 32'h0, OKAY);
        wr(8'h08, 32'h12345678, 4'hF, SLVERR);
        rd_chk(8'h08, 32'h0, OKAY);
        wr(8'h01, 32'h00000007, 4'hF, SLVERR);
        wr(8'h05, 32'hFFFFFFFF, 4'hF, SLVERR);
        wr(8'h06, 32'hFFFFFFFF, 4'hF, SLVERR);
        wr(8'h0F, 32'h00000001, 4'hF, SLVERR);
        rd_chk(8'h04, 32'hCAFEF00D, OKAY);
        rd_chk(8'h00, 32'h0, OKAY);
        rd_chk(8'h01, 32'h0, SLVERR);
        rd_chk(8'h02, 32'h0, SLVERR);
        rd_chk(8'h05, 32'h0, SLVERR);
        rd_chk(8'h0E, 32'h0, SLVERR);
        // Offsets from 0x10 up: ADDR_WIDTH 8 lane only
        lane4_en = 1'b0;
        wr(8'h10, 32'h00000007, 4'hF, SLVERR);
        wr(8'h14, 32'hFFFFFFFF, 4'hF, SLVERR);
        wr(8'h18, 32'hFFFFFFFF, 4'hF, SLVERR);
        wr(8'h1C, 32'h00000001, 4'hF, SLVERR);
        wr(8'h84, 32'h00000000, 4'hF, SLVERR);
        wr(8'hF0, 32'h00000007, 4'hF, SLVERR);
        rd_chk(8'h10, 32'h0, SLVERR);
        rd_chk(8'h14, 32'h0, SLVERR);
        rd_chk(8'h84, 32'h0, SLVERR);
        rd_chk(8'hFC, 32'h0, SLVERR);
        lane4_en = 1'b1;
        rd_chk(8'h04, 32'hCAFEF00D, OKAY);
        rd_chk(8'h00, 32'h0, OKAY);
        rd_chk(8'h08, 32'h0, OKAY);
        chk(irq8 == 1'b0);

        // 5. CTRL write without wstrb[0]; CTRL upper bits read as zero
        phase = 5;
        wr(8'h00, 32'hFFFFFFFF, 4'b1110, OKAY);
        rd_chk(8'h00, 32'h0, OKAY);
        idle(5);
        rd_chk(8'h08, 32'h0, OKAY);
        wr(8'h00, 32'hFFFFFFF4, 4'hF, OKAY);
        rd_chk(8'h00, 32'h4, OKAY);
        wr(8'h00, 32'h0, 4'hF, OKAY);
        rd_chk(8'h00, 32'h0, OKAY);

        // 6. One-shot counts timed to the edge
        phase = 6;
        wr(8'h04, 32'd5, 4'hF, OKAY);
        rises0 = irq_rises;
        wr(8'h00, 32'h3, 4'hF, OKAY);
        E = last_wr_edge;
        wait_irq(100);
        chk(last_irq_rise == E + 5);
        chk(irq_rises == rises0 + 1);
        rd_chk(8'h00, 32'h2, OKAY);       // EN cleared itself, IE kept
        rd_chk(8'h08, 32'h0, OKAY);
        rd_chk(8'h0C, 32'h1, OKAY);
        wr(8'h0C, 32'h0, 4'hF, OKAY);     // writing 0 does not clear
        chk(irq8 == 1'b1);
        wr(8'h0C, 32'h1, 4'b1110, OKAY);  // no wstrb[0]: no clear
        chk(irq8 == 1'b1);
        rd_chk(8'h0C, 32'h1, OKAY);
        wr(8'h0C, 32'h1, 4'h1, OKAY);     // clear
        chk(irq8 == 1'b0);
        rd_chk(8'h0C, 32'h0, OKAY);
        idle(30);
        chk((irq8 == 1'b0) && (irq_rises == rises0 + 1));   // no second interrupt
        rd_chk(8'h0C, 32'h0, OKAY);
        rd_chk(8'h08, 32'h0, OKAY);
        // LOAD of 1
        wr(8'h04, 32'd1, 4'hF, OKAY);
        wr(8'h00, 32'h3, 4'hF, OKAY);
        E = last_wr_edge;
        wait_irq(20);
        chk(last_irq_rise == E + 1);
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        rd_chk(8'h00, 32'h2, OKAY);
        // LOAD of 0 counts as 1
        wr(8'h04, 32'd0, 4'hF, OKAY);
        wr(8'h00, 32'h3, 4'hF, OKAY);
        E = last_wr_edge;
        wait_irq(20);
        chk(last_irq_rise == E + 1);
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        rd_chk(8'h00, 32'h2, OKAY);
        rd_chk(8'h08, 32'h0, OKAY);

        // 7. Interrupt enable on a pending expiry
        phase = 7;
        wr(8'h04, 32'd3, 4'hF, OKAY);
        wr(8'h00, 32'h1, 4'hF, OKAY);     // EN, IE 0, one-shot
        idle(10);
        chk(irq8 == 1'b0);
        rd_chk(8'h0C, 32'h1, OKAY);
        rd_chk(8'h00, 32'h0, OKAY);
        wr(8'h00, 32'h2, 4'hF, OKAY);     // IE 1
        W = last_wr_edge;
        chk(irq8 == 1'b1);
        chk(last_irq_rise == W);
        wr(8'h00, 32'h0, 4'hF, OKAY);     // IE 0 drops irq
        chk(irq8 == 1'b0);
        rd_chk(8'h0C, 32'h1, OKAY);
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        rd_chk(8'h0C, 32'h0, OKAY);

        // 8. Periodic counts over several periods
        phase = 8;
        wr(8'h04, 32'd12, 4'hF, OKAY);
        rises0 = irq_rises;
        wr(8'h00, 32'h7, 4'hF, OKAY);     // EN, IE, periodic
        E = last_wr_edge;
        wait_irq(100);
        chk(last_irq_rise == E + 12);
        rd_chk(8'h00, 32'h7, OKAY);       // EN stays 1
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        chk(irq8 == 1'b0);
        wait_irq(100);
        chk(last_irq_rise == E + 24);
        // Acknowledge on the very edge the third count ends
        wait_edge(E + 35);
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        chk(last_wr_edge == E + 36);
        chk(irq8 == 1'b1);                // the new expiry is kept
        rd_chk(8'h0C, 32'h1, OKAY);
        axi_read(8'h08, 0, d, r);         // COUNT mid-period
        expv = 12 - (last_rd_edge - 1 - (E + 36));
        chk32(d, expv);
        chk_resp(r, OKAY);
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        chk(irq8 == 1'b0);
        wait_irq(100);
        chk(last_irq_rise == E + 48);
        chk(irq_rises == rises0 + 3);
        wr(8'h00, 32'h0, 4'hF, OKAY);
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        rd_chk(8'h00, 32'h0, OKAY);
        chk(irq8 == 1'b0);

        // 9. A stop freezes COUNT
        phase = 9;
        wr(8'h04, 32'd100, 4'hF, OKAY);
        wr(8'h00, 32'h1, 4'hF, OKAY);
        E = last_wr_edge;
        idle(10);
        wr(8'h00, 32'h0, 4'hF, OKAY);
        S = last_wr_edge;
        expv = 100 - (S - E);
        rd_chk(8'h08, expv, OKAY);
        idle(20);
        rd_chk(8'h08, expv, OKAY);
        rd_chk(8'h0C, 32'h0, OKAY);
        rd_chk(8'h00, 32'h0, OKAY);

        // 10. A restart counts again from LOAD
        phase = 10;
        wr(8'h04, 32'd20, 4'hF, OKAY);
        rises0 = irq_rises;
        wr(8'h00, 32'h3, 4'hF, OKAY);
        E = last_wr_edge;
        idle(8);
        wr(8'h00, 32'h3, 4'hF, OKAY);
        E2 = last_wr_edge;
        chk(E2 > E);
        wait_irq(100);
        chk(last_irq_rise == E2 + 20);
        chk(irq_rises == rises0 + 1);
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        wr(8'h00, 32'h0, 4'hF, OKAY);
        chk(irq8 == 1'b0);

        // 11. CTRL write on the edge a count ends: the write wins for EN and COUNT
        phase = 11;
        wr(8'h04, 32'd8, 4'hF, OKAY);
        wr(8'h00, 32'h3, 4'hF, OKAY);     // one-shot
        E = last_wr_edge;
        wait_edge(E + 7);
        wr(8'h00, 32'h3, 4'hF, OKAY);     // restart on the end edge
        chk(last_wr_edge == E + 8);
        chk(irq8 == 1'b1);
        chk(last_irq_rise == E + 8);
        rd_chk(8'h00, 32'h3, OKAY);
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        chk(irq8 == 1'b0);
        wait_irq(100);
        chk(last_irq_rise == E + 16);
        rd_chk(8'h00, 32'h2, OKAY);
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        wr(8'h00, 32'h7, 4'hF, OKAY);     // periodic
        E = last_wr_edge;
        wait_edge(E + 7);
        wr(8'h00, 32'h6, 4'hF, OKAY);     // stop on the end edge
        chk(last_wr_edge == E + 8);
        chk(irq8 == 1'b1);
        rd_chk(8'h00, 32'h6, OKAY);
        rd_chk(8'h08, 32'd8, OKAY);       // COUNT as the end edge gave it
        rd_chk(8'h0C, 32'h1, OKAY);
        idle(20);
        rd_chk(8'h08, 32'd8, OKAY);
        wr(8'h0C, 32'h1, 4'hF, OKAY);
        chk(irq8 == 1'b0);
        wr(8'h00, 32'h0, 4'hF, OKAY);

        // 12. Reset during a count, with a held write address
        phase = 12;
        wr(8'h04, 32'd5, 4'hF, OKAY);
        wr(8'h00, 32'h7, 4'hF, OKAY);
        idle(20);
        chk(irq8 == 1'b1);
        chk(awready8);
        awaddr  = 8'h04;
        awvalid = 1'b1;
        @(negedge clk);
        awvalid = 1'b0;
        chk(!awready8 && wready8 && !bvalid8);   // address held alone
        aresetn = 1'b0;
        idle(2);
        aresetn = 1'b1;
        chk((irq8 == 1'b0) && (irq4 == 1'b0));
        chk(awready8 && wready8 && arready8 && !bvalid8 && !rvalid8);
        rd_chk(8'h00, 32'h0, OKAY);
        rd_chk(8'h04, 32'h0, OKAY);
        rd_chk(8'h08, 32'h0, OKAY);
        rd_chk(8'h0C, 32'h0, OKAY);
        // Data alone must not complete with a stale held address
        wdata  = 32'h0000BEEF;
        wstrb  = 4'hF;
        wvalid = 1'b1;
        @(negedge clk);
        wvalid = 1'b0;
        chk(!wready8 && awready8 && !bvalid8);
        idle(2);
        chk(!bvalid8);
        awaddr  = 8'h04;
        awvalid = 1'b1;
        @(negedge clk);
        awvalid = 1'b0;
        chk(bvalid8 && (bresp8 == OKAY));
        bready = 1'b1;
        @(negedge clk);
        bready = 1'b0;
        chk(!bvalid8);
        rd_chk(8'h04, 32'h0000BEEF, OKAY);
        rises0 = irq_rises;
        idle(60);
        chk((irq8 == 1'b0) && (irq_rises == rises0));
        rd_chk(8'h08, 32'h0, OKAY);
        rd_chk(8'h0C, 32'h0, OKAY);

        // Verdict
        phase = 99;
        idle(2);
        nchk = nchk + 1;
        if (mon_fail == 0) begin
            passed = passed + 1;
        end else begin
            failed = failed + mon_fail;
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: a hung run still ends with one verdict, marked failed.
    initial begin
        #1000000;
        $error("watchdog timeout in phase %0d", phase);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + mon_fail + 1);
        $finish;
    end

endmodule

`default_nettype wire
